#!/bin/bash
# ============================================================
# Installer untuk audit-b fix (commit e73533e)
# ============================================================
# Cara pakai:
#   1. Download script ini ke VPS
#   2. bash install-audit-b-fix.sh
#
# Script akan:
#   - Decode patch dari base64 di bawah
#   - Apply ke repo ~/sayurlogi via git am
#   - Rebuild + restart PM2
# ============================================================
set -e

REPO_DIR="${HOME}/sayurlogi"
PATCH_FILE="/tmp/audit-b-fix.patch"

if [ ! -d "$REPO_DIR/.git" ]; then
  echo "ERROR: Repo $REPO_DIR tidak ditemukan."
  exit 1
fi

echo "==> Step 1: Decode patch dari base64..."
base64 -d > "$PATCH_FILE" << "PATCH_BASE64_EOF"

PATCH_BASE64_EOF

echo "   Patch tersimpan: $PATCH_FILE ($(wc -c < $PATCH_FILE) bytes)"

cd "$REPO_DIR"
echo ""
echo "==> Step 2: Cek repo state..."
git status --short
git log --oneline -1

echo ""
echo "==> Step 3: Apply patch via git am..."
git am < "$PATCH_FILE"
echo "   ✓ Patch applied"

echo ""
echo "==> Step 4: Build production..."
bun run build

echo ""
echo "==> Step 5: Restart PM2..."
pm2 restart sayurlogi
sleep 3

echo ""
echo "==> Step 6: Verifikasi..."
git log --oneline -3
echo ""
echo "==> Startup logs:"
pm2 logs sayurlogi --lines 15 --nostream

echo ""
echo "==> Test register (harus 200, tanpa Invalid URL):"
curl -s -X POST http://localhost:3000/api/customer/register \
  -H "Content-Type: application/json" \
  -d '{"name":"Verify Fix","email":"verify@deploy.id","phone":"08123456999","password":"test123"}' | head -c 300
echo ""

echo ""
echo "==> Cek error lama:"
pm2 logs sayurlogi --lines 20 --nostream | grep -iE "Invalid URL|register|ERPNext sync failed" | head -5
echo ""
echo "============================================================"
echo "✓ SELESAI. Commit e73533e (audit-b fix) sudah aktif di VPS."
echo "============================================================"
